import {VERSION,TABLES,uid,day,active,empty,range,statistics,validate,snapshot,validDate} from './core.mjs';
import {readStore,writeStore,readPrevious} from './storage.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4z M12 6v15',home:'m3 10 9-7 9 7 M5 9v12h5v-7h4v7h5V9',thought:'M9 18h6 M10 21h4 M8 14a7 7 0 1 1 8 0l-1 4H9z',flask:'M9 3h6 M10 3v7L4 20q0 1 2 1h12q2 0 2-1l-6-10V3 M7 15h10',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 21H2',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 m-6-6 6 6-6 6',back:'m15 5-7 7 7 7',close:'m6 6 12 12 M6 18 18 6',leaf:'M20 3C6 2 2 9 6 17c8 4 15-3 14-14z M5 21 16 9',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',edit:'m16 3 5 5-12 12-6 1 1-6z M13 6l5 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',check:'m5 12 4 4L19 6',link:'M9 15l6-6 M7 13l-3 3a3 3 0 0 0 4 4l4-4 M12 8l4-4a3 3 0 0 1 4 4l-3 3',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',more:'M5 12h.01 M12 12h.01 M19 12h.01',shield:'m12 2 9 4v7c0 5-9 9-9 9S3 18 3 13V6z m-5 10 3 3 5-5',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const btn=(text,action,id='',kind='')=>`<button class="btn ${kind}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const textBtn=(text,action,id='')=>`<button class="text-btn" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const chip=(s)=>`<span class="chip ${s==='需要修正'||s==='待复盘'?'amber':''}">${esc(s)}</span>`;
let db,route,filters={books:'全部',thoughts:'全部',experiments:'全部',stats:'month'},bookTab='阅读',thoughtTab='当前理解',searchQuery='',globalSearchQuery='',tagFilter='',statDate=day(),statEnd=day(),thoughtSort='updated',modalKey='',modalCallback=null,focusBefore=null,toastTimer,offlineReady=false,pendingImport=null,pendingExport=null,busy=false;
const statuses=['新收获','思考中','实践中','暂时认可','需要修正'];
const book=id=>db.books.find(x=>x.id===id),thought=id=>db.thoughts.find(x=>x.id===id),experiment=id=>db.experiments.find(x=>x.id===id);
const titleBook=id=>{const b=book(id);return b?b.title+(b.deletedAt?'（已删除）':''):'来源已移除'};
const niceDate=d=>new Date(d+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
const dateTime=()=>new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});
const stamp=()=>new Date().toISOString();
const fresh=()=>({id:uid(),createdAt:stamp(),updatedAt:stamp()});
function expStatus(e){return e.status==='进行中'&&e.due&&e.due<=day()?'待复盘':e.status}
function toast(msg,undo){clearTimeout(toastTimer);$('#toast').innerHTML=esc(msg)+(undo?'<button id="undo-toast">撤销</button>':'');$('#toast').classList.add('show');if(undo)$('#undo-toast').onclick=undo;toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),undo?8000:4000)}
async function commit(change,{previous=null,renderAfter=true}={}){const next=structuredClone(db);await change(next);next.updatedAt=new Date(Math.max(Date.now(),Date.parse(db.updatedAt)+1)).toISOString();await writeStore(next,previous,db.updatedAt);db=next;if(renderAfter)render();}
function go(path){if(location.hash.slice(1)===path)render();else location.hash=path}
const navs=[['today','home','今日'],['books','book','书架'],['thoughts','thought','思想'],['experiments','flask','实践'],['me','chart','我的']];
function navActive(n){return n===(route[0]==='book'?'books':route[0]==='thought'?'thoughts':route[0]==='experiment'?'experiments':['stats','reports','report','settings','trash'].includes(route[0])?'me':route[0]);}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="./icon-blue.png" alt=""><div><strong>拾页</strong><small>READ · THINK · GROW</small></div></div><div class="side-caption">我的阅读空间</div><nav aria-label="主导航">${navs.map(([k,i,t])=>`<a href="#${k}" class="nav-item ${navActive(k)?'active':''}" ${navActive(k)?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav><div class="side-bottom"><div><span class="dot"></span>记录保存在此设备</div><div style="margin-top:7px">让每一页，都留下回响。</div></div></aside><main class="main"><div class="mobile-brand"><img src="./icon-blue.png" alt="">拾页<span>记录阅读，积累思想</span></div>${content}<p class="footer-note">慢慢读，慢慢想，让改变发生。</p></main><nav class="bottom-nav" aria-label="底部导航">${navs.map(([k,i,t])=>`<a href="#${k}" class="${navActive(k)?'active':''}" ${navActive(k)?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}</nav></div>`}
function heading(title,sub='',action='',label='YOUR READING SPACE'){return `<header class="topbar"><div><div class="eyebrow">${label}</div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div><div class="top-actions">${action}<button class="icon-btn" data-action="search" aria-label="全局搜索">${icon('search')}</button></div></header>`}
function emptyView(title,description,action=''){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${description}</p>${action}</div>`}
function cover(b,large=false){return `<div class="book-cover tone${[...b.id].reduce((s,c)=>s+c.charCodeAt(0),0)%4}${large?' large':''}" aria-hidden="true"><b>${esc(b.title)}</b><small>${esc(b.author||'我的阅读档案')}</small></div>`}
function progress(b){const p=b.percent!==null?b.percent:b.total?Math.min(100,Math.round(b.position/b.total*100)):null;return `${p!==null?`<div class="progress"><span style="width:${p}%"></span></div>`:''}<div class="row small muted"><span>${b.percent!==null?'电子书进度':b.position?'读至第 '+b.position+' 页':'尚未记录当前位置'}</span><span>${p!==null?p+'%':'—'}</span></div>`}
function bookCard(b){return `<article class="card clickable" data-action="open-book" data-id="${b.id}" tabindex="0" role="button" aria-label="打开${esc(b.title)}"><div class="book-row">${cover(b)}<div class="book-info"><h3>${esc(b.title)}</h3><p class="small muted">${esc(b.author||'作者未填写')}</p>${progress(b)}</div></div><div class="card-foot">${chip(b.status)}<span>${active(db.logs).filter(l=>l.bookId===b.id).reduce((s,l)=>s+l.pages,0)} 页累计阅读</span></div></article>`}
function logRow(l){return `<div class="record"><span class="record-time">${l.time}</span><div class="record-body"><button class="text-btn record-title" style="color:var(--ink);padding:0;min-height:24px" data-action="edit-log" data-id="${l.id}">${esc(titleBook(l.bookId))}</button><div class="small muted">${l.pages} 页${l.minutes!==null?' · '+l.minutes+' 分钟':' · 时长未记录'}</div>${l.note?`<p>${esc(l.note)}</p>`:''}<div class="row left gap">${l.note?textBtn('提炼为思想 '+icon('arrow'),'from-log',l.id):''}${textBtn('编辑','edit-log',l.id)}</div></div></div>`}
function thoughtCard(t){return `<article class="card thought-card clickable" data-action="open-thought" data-id="${t.id}" tabindex="0" role="button"><div class="row"><span class="small muted">${t.bookIds.length?'来自《'+esc(titleBook(t.bookIds[0]))+'》':'我的独立思考'}</span>${chip(t.status)}</div><h3 style="margin-top:15px">${esc(t.title)}</h3><p>${esc(t.understanding)}</p><div class="chips">${t.tags.map(v=>`<span class="chip"># ${esc(v)}</span>`).join('')}</div><div class="card-foot"><span>${day(new Date(t.updatedAt))}</span><span>${t.history.length} 次留痕 ${icon('arrow')}</span></div></article>`}
function experimentCard(e){return `<article class="card clickable" data-action="open-experiment" data-id="${e.id}" tabindex="0" role="button"><div class="row">${chip(expStatus(e))}${icon('flask')}</div><h3 style="margin-top:15px">${esc(e.title)}</h3><p class="small muted" style="margin-top:10px;white-space:pre-wrap">${esc(e.hypothesis)}</p><div class="card-foot"><span>${e.due?'复盘 '+e.due:'未设定复盘日期'}</span><span>${e.feedback.filter(f=>!f.deletedAt).length} 条反馈</span></div></article>`}
function renderToday(){const today=day(),s=statistics(db,today,today),w=statistics(db,...range('week')),reading=active(db.books).filter(b=>b.status==='在读').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)),latest=active(db.thoughts).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0],due=active(db.experiments).filter(e=>expStatus(e)==='待复盘');return heading('今天，读到哪里了？',niceDate(today),'','A LITTLE READING, EVERY DAY')+`<div class="two-col"><div class="stack"><section class="hero"><div class="hero-top"><span class="hero-label">今日阅读 · ${today.replaceAll('-','.')}</span>${icon('book')}</div><div class="hero-stat">${s.pages}<span>页</span></div><p class="small" style="color:#bdcdbd">${s.logs.length?'每一页，都在成为你的积累。':'从一页开始，给自己留一点阅读时间。'}</p><div class="hero-grid"><div><strong>${s.minutes}<small> 分钟</small></strong><small>今日已记录时长</small></div><div><strong>${w.pages}<small> 页</small></strong><small>本周累计阅读</small></div><div><strong>${s.logs.length}<small> 次</small></strong><small>今日阅读记录</small></div></div></section><div>${btn(icon('plus')+'记录阅读','new-log','','full')}<p class="form-help" style="text-align:center;margin:8px 0 0">只记页数也可以。想法，慢慢写。</p></div><section><div class="section-head"><h2>今天的足迹 <small>${s.logs.length} 条</small></h2>${textBtn(icon('calendar')+' 补录 / 历史','history')}</div><div class="card">${s.logs.length?s.logs.sort((a,b)=>b.time.localeCompare(a.time)).map(logRow).join(''):emptyView('今天的第一页，等你留下','读完后花半分钟，记下属于你的收获。')}</div></section></div><div class="stack"><section><div class="section-head"><h2>正在阅读</h2>${textBtn('全部书籍 '+icon('arrow'),'books')}</div>${reading.length?`<div class="stack">${reading.slice(0,2).map(bookCard).join('')}</div>`:`<div class="card">${emptyView('准备好一本书','从想读的那一本开始。',btn(icon('plus')+' 添加书籍','new-book','','secondary'))}</div>`}</section>${due.length?`<div class="banner warn">${icon('flask')}<div>${due.length} 个实验到了复盘时间<br>${textBtn('去看看 →','experiments')}</div></div>`:''}<section><div class="section-head"><h2>最近的思考</h2>${textBtn('思想库 '+icon('arrow'),'thoughts')}</div>${latest?thoughtCard(latest):`<div class="card quote"><div class="quote-mark">“</div><p>读过的文字，会慢慢变成<br>看待世界的角度。</p><small>发现一个值得留下的想法时，再记下来。</small>${textBtn('写下一个想法 →','new-thought')}</div>`}</section></div></div>`}
function localSearch(placeholder){return `<div class="searchbox">${icon('search')}<input id="local-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(searchQuery)}"></div>`}
function tabs(values,current,key){return `<div class="pill-tabs" role="group" aria-label="筛选">${values.map(x=>`<button data-action="filter" data-key="${key}" data-id="${x}" class="${current===x?'selected':''}" aria-pressed="${current===x}">${x}</button>`).join('')}</div>`}
function renderBooks(){const q=searchQuery.toLowerCase(),list=active(db.books).filter(b=>(filters.books==='全部'||b.status===filters.books)&&(b.title+' '+b.author).toLowerCase().includes(q));return heading('我的书架','读过的每一本书，都有自己的故事。',btn(icon('plus')+'添加书籍','new-book'),'THE BOOKS WE KEEP')+localSearch('搜索书名、作者')+tabs(['全部','想读','在读','已读','暂停'],filters.books,'books')+`<div class="grid">${list.map(bookCard).join('')}</div>`+(!list.length?emptyView('书架留着位置','添加一本书，开始建立你的个人阅读档案。',btn('添加第一本书','new-book')):'')}
function renderBook(id){const b=book(id);if(!b)return missing();const logs=active(db.logs).filter(l=>l.bookId===id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),ts=active(db.thoughts).filter(t=>t.bookIds.includes(id));return textBtn(icon('back')+' 返回书架','books')+`<div class="detail-header">${cover(b,true)}<div><p class="eyebrow">MY READING ARCHIVE</p><h1>${esc(b.title)}</h1><p class="subtitle">${esc(b.author||'作者未填写')}</p><div class="chips">${chip(b.status)}${b.deletedAt?chip('已移入回收站'):''}</div></div></div><div class="card"><div class="detail-meta"><span><b>${logs.reduce((s,l)=>s+l.pages,0)} 页</b>累计阅读 · 含重读</span><span><b>${logs.reduce((s,l)=>s+(l.minutes||0),0)} 分钟</b>已记录时长</span><span><b>${logs.length} 次</b>阅读记录</span><span><b>${ts.length} 张</b>思想卡片</span></div>${progress(b)}<p class="small muted" style="margin-top:12px">${b.started?'开始：'+b.started:''} ${b.finished?'　完成：'+b.finished:''}</p><div class="action-wrap" style="margin-top:18px">${!b.deletedAt?btn(icon('plus')+'记录阅读','new-log',id):''}${btn('编辑资料','edit-book',id,'secondary')}${!b.deletedAt&&b.status!=='已读'?btn('标记已读','finish-book',id,'secondary'):''}${btn(icon('download')+'导出笔记','export-book',id,'secondary')}${!b.deletedAt?textBtn('移入回收站','delete-book',id):''}</div></div><div class="section">${tabs(['阅读','收获','思想','总结'],bookTab,'bookTab')}${bookTab==='阅读'?`<div class="card">${logs.length?logs.map(l=>`<div class="small muted" style="margin-top:14px">${l.date}</div>${logRow(l)}`).join(''):emptyView('还没有阅读记录','开始阅读时，来这里留下第一条。')}</div>`:bookTab==='收获'?`<div class="card">${logs.filter(l=>l.note).map(logRow).join('')||emptyView('收获会慢慢累积','记录阅读时，可以顺手写下一句话。')}</div>`:bookTab==='思想'?`${btn(icon('plus')+'新建思想','book-thought',id,'secondary')}<div class="grid two" style="margin-top:18px">${ts.map(thoughtCard).join('')}</div>`:`<div class="card"><div class="section-head"><h2>我的读后总结</h2>${textBtn('编辑总结','summary',id)}</div><p class="small muted">个人评分：${b.rating?'★'.repeat(b.rating)+'☆'.repeat(5-b.rating):'尚未评分'}</p><div class="prose" style="margin-top:16px">${esc(b.summary)||'这本书讲了什么？哪些观点影响了你？又有哪些地方值得质疑？'}</div></div>`}</div>`}
function renderThoughts(){const q=searchQuery.toLowerCase(),list=active(db.thoughts).filter(t=>(filters.thoughts==='全部'||t.status===filters.thoughts)&&(!tagFilter||t.tags.includes(tagFilter))&&[t.title,t.understanding,t.question,t.authorView,...t.tags,...t.bookIds.map(titleBook)].join(' ').toLowerCase().includes(q)).sort((a,b)=>thoughtSort==='created'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt));const tags=[...new Set(active(db.thoughts).flatMap(t=>t.tags))];return heading('思想，慢慢生长','把别人的观点，变成自己的理解。',btn(icon('plus')+'写想法','new-thought'),'A GARDEN OF IDEAS')+localSearch('搜索观点、问题或标签')+`<label class="field" style="max-width:180px">排序<select id="thought-sort"><option value="updated" ${thoughtSort==='updated'?'selected':''}>最近更新</option><option value="created" ${thoughtSort==='created'?'selected':''}>最近创建</option></select></label>`+tabs(['全部',...statuses],filters.thoughts,'thoughts')+`<div class="chips" style="margin-bottom:20px">${tags.map(t=>`<button class="chip tag-button ${tagFilter===t?'amber':''}" data-action="tag" data-id="${esc(t)}"># ${esc(t)}${tagFilter===t?' ×':''}</button>`).join('')}</div><div class="grid two">${list.map(thoughtCard).join('')}</div>`+(!list.length?emptyView('留住让你停下来想一想的那句话','可以是理解、疑问，也可以是暂时没有答案的想法。',btn('写下一个想法','new-thought')):'')}
function renderThought(id){const t=thought(id);if(!t)return missing();const incoming=active(db.thoughts).flatMap(o=>o.links.filter(l=>l.target===id).map(l=>({other:o,link:l,incoming:true}))),outgoing=t.links.map(l=>({other:thought(l.target),link:l,incoming:false})).filter(x=>x.other);const experiments=active(db.experiments).filter(e=>e.thoughtIds.includes(id));return textBtn(icon('back')+' 返回思想','thoughts')+heading(esc(t.title),'创建于 '+day(new Date(t.createdAt)),btn('更新判断','judgment',id),'THINKING, IN PROGRESS')+`<div class="row wrap"><div class="chips">${chip(t.status)}${t.tags.map(x=>chip('# '+x)).join('')}${t.deletedAt?chip('已删除'):''}</div><div class="action-wrap">${textBtn(icon('edit')+' 编辑文字','edit-thought',id)}${textBtn(icon('flask')+' 开始实践','thought-experiment',id)}${!t.deletedAt?textBtn('删除','delete-thought',id):''}</div></div><div class="section">${tabs(['当前理解','变化记录'],thoughtTab,'thoughtTab')}${thoughtTab==='当前理解'?`<div class="two-col"><div class="stack"><div class="card">${[['我的理解',t.understanding],['作者观点',t.authorView],['仍然好奇的问题',t.question]].filter(x=>x[1]).map(([l,v])=>`<section class="field-section"><div class="label-heading">${l}</div><div class="prose">${esc(v)}</div></section>`).join('')}<div class="divider"></div><div class="label-heading">思想来源</div>${t.bookIds.map(b=>`<div>${textBtn(icon('book')+' '+esc(titleBook(b)),'open-book',b)}</div>`).join('')||'<p class="small muted">独立思考，未关联书籍</p>'}${t.logId?textBtn('查看原阅读记录','edit-log',t.logId):''}</div></div><div class="stack"><div class="card"><div class="section-head"><h3>关联思想</h3>${textBtn('＋ 关联','link-thought',id)}</div>${[...outgoing,...incoming].map(x=>`<div class="link-row"><div>${textBtn(esc(x.other.title),'open-thought',x.other.id)}<p>${x.incoming?'此观点被对方'+esc(x.link.type):'此观点'+esc(x.link.type)+'对方'}${x.other.deletedAt?' · 对方已删除':''}</p>${x.link.reason?`<p>${esc(x.link.reason)}</p>`:''}</div>${textBtn('移除','unlink',JSON.stringify({owner:x.incoming?x.other.id:t.id,target:x.incoming?t.id:x.other.id}))}</div>`).join('')||'<p class="small muted">不同的书，也可能在回答同一个问题。</p>'}</div><div class="card"><div class="section-head"><h3>相关实践</h3></div>${experiments.map(e=>textBtn(esc(e.title)+' →','open-experiment',e.id)).join('<br>')||'<p class="small muted">不必急着实践，先让理解沉淀。</p>'}</div></div></div>`:`<div class="timeline">${[...t.history].reverse().map(h=>`<article class="timeline-item"><div class="small muted">${day(new Date(h.at))} · ${esc(h.kind)}</div><div class="card"><div class="row"><h3>${esc(h.title)}</h3>${chip(h.status)}</div><div class="prose" style="margin-top:14px">${esc(h.understanding)}</div>${h.reason?`<div class="inset-note">改变的原因：${esc(h.reason)}</div>`:''}${h.experimentId?textBtn('查看实践证据 →','open-experiment',h.experimentId):''}<div>${textBtn('恢复到这一版','restore-thought',JSON.stringify({id,hid:h.id}))}</div></div></article>`).join('')}</div>`}</div>`}
function renderExperiments(){const list=active(db.experiments).filter(e=>filters.experiments==='全部'||expStatus(e)===filters.experiments).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return heading('让想法，走进生活','小步尝试，观察反馈，再更新判断。',btn(icon('plus')+'新建实验','new-experiment'),'IDEAS INTO EVERYDAY LIFE')+tabs(['全部','进行中','待复盘','已结束','已暂停'],filters.experiments,'experiments')+`<div class="grid two">${list.map(experimentCard).join('')}</div>`+(!list.length?emptyView('从一个小小的尝试开始','你想验证什么？准备怎样观察它？',btn('创建第一个实验','new-experiment')):'')}
function renderExperiment(id){const e=experiment(id);if(!e)return missing();return textBtn(icon('back')+' 返回实践','experiments')+heading(esc(e.title),'开始于 '+e.start+(e.due?' · 预计复盘 '+e.due:''),btn('添加反馈','feedback',id),'A SMALL EXPERIMENT')+`<div class="row wrap">${chip(expStatus(e))}<div class="action-wrap">${textBtn('编辑计划','edit-experiment',id)}${e.status==='已结束'?textBtn('重新开始','reopen-experiment',id):textBtn(e.status==='已暂停'?'继续实验':'暂停实验','pause-experiment',id)}${e.status!=='已结束'?textBtn('结束并复盘','conclude',id):''}${!e.deletedAt?textBtn('删除','delete-experiment',id):''}</div></div><div class="two-col section"><div class="stack"><section class="card">${[['想验证的想法',e.hypothesis],['准备采取的行动',e.action],['观察线索',e.observe],['调整或停止条件',e.stop]].filter(x=>x[1]).map(([k,v])=>`<div class="field-section"><div class="label-heading">${k}</div><div class="prose">${esc(v)}</div></div>`).join('')}</section><section><div class="section-head"><h2>过程与反馈</h2>${textBtn('＋ 添加','feedback',id)}</div><div class="timeline">${e.feedback.filter(f=>!f.deletedAt).sort((a,b)=>b.date.localeCompare(a.date)).map(f=>`<div class="timeline-item"><span class="small muted">${f.date}</span><div class="card"><div class="prose">${esc(f.event)}</div>${f.meaning?`<div class="inset-note">${esc(f.meaning)}</div>`:''}${textBtn('编辑反馈','edit-feedback',JSON.stringify({id,fid:f.id}))}</div></div>`).join('')||'<p class="small muted">记录一个具体经历，就有了第一条证据。</p>'}</div></section></div><div class="stack"><section class="card"><h3>思想来源</h3>${e.thoughtIds.map(t=>`<div>${textBtn(esc(thought(t)?.title||'来源已移除'),'open-thought',t)}</div>`).join('')||'<p class="small muted" style="margin-top:12px">未关联思想卡片</p>'}</section><section class="card"><div class="section-head"><h3>复盘结论</h3>${textBtn('编辑','conclude',id)}</div>${e.verdict?chip(e.verdict):''}<div class="prose" style="margin-top:12px">${esc(e.conclusion)||'证据可以慢慢积累，不必急着得出结论。'}</div>${e.conclusion&&e.thoughtIds.length?`<div class="divider"></div><p class="small muted">把这次经历带回你的思想卡片：</p>${e.thoughtIds.map(t=>textBtn('更新「'+esc(thought(t)?.title)+'」','judgment-evidence',JSON.stringify({tid:t,eid:id}))).join('<br>')}`:''}</section></div></div>`}
function missing(){return emptyView('没有找到这条内容','可能已被永久删除。',btn('回到今日','today'))}
function renderMe(){const total=statistics(db,'0000-01-01','9999-12-31'),last=db.settings.lastBackup,needsBackup=!last||Date.now()-Date.parse(last)>7*86400000;return heading('回看，也是一种生长','这里收藏着阅读留下的改变。','','LOOK BACK, MOVE FORWARD')+`<div class="card"><div class="row"><div class="brand"><img src="./icon-blue.png" alt=""><div><h2>我的阅读空间</h2><p class="small muted">${active(db.books).length} 本书，${active(db.thoughts).length} 个留下的想法</p></div></div>${chip('本地保存')}</div><div class="stat-grid"><button class="stat-card" data-action="stats"><strong>${total.pages}</strong><span>累计阅读 / 页</span></button><button class="stat-card" data-action="books"><strong>${total.books}</strong><span>已读书籍 / 本</span></button><button class="stat-card" data-action="thoughts"><strong>${active(db.thoughts).length}</strong><span>思想卡片 / 张</span></button><button class="stat-card" data-action="experiments"><strong>${active(db.experiments).length}</strong><span>实践实验 / 个</span></button></div></div>${db.settings.remindBackup&&needsBackup?`<div class="banner warn" style="margin-top:20px">${icon('shield')}<div>给积累留一份备份。<br><span class="small">${last?'上次导出：'+last.slice(0,10):'还没有导出过备份'}。本地保存不等于独立备份。</span></div>${textBtn('导出','backup')}</div>`:''}<div class="grid two section"><div class="card settings-list"><button data-action="stats">${icon('chart')}<span>成长统计<small>阅读轨迹、关注主题、实践变化</small></span>${icon('arrow')}</button><button data-action="reports">${icon('file')}<span>周期复盘<small>每日、每周、每月、每年</small></span>${icon('arrow')}</button><button data-action="settings">${icon('settings')}<span>数据与设置<small>备份恢复、使用帮助、回收站</small></span>${icon('arrow')}</button></div><div class="card quote"><div class="quote-mark">“</div><p>不只是记得读过什么，<br>也记得自己如何改变。</p><small>拾页 · 记录阅读，积累思想</small></div></div>`}
function renderStats(){const [start,end]=filters.stats==='custom'?[statDate,statEnd]:range(filters.stats,statDate),s=statistics(db,start,end),tags={};active(db.thoughts).filter(t=>day(new Date(t.createdAt))>=start&&day(new Date(t.createdAt))<=end).forEach(t=>t.tags.forEach(v=>tags[v]=(tags[v]||0)+1));const counts={};s.logs.forEach(l=>counts[l.date]=(counts[l.date]||0)+l.pages);let days=[];for(let d=new Date(start+'T12:00:00');day(d)<=end;d.setDate(d.getDate()+1)){days.push(day(d));if(days.length>36600)break}const chartDays=days.length>31?[...new Set(days.map(d=>d.slice(0,7)))]:days;const vals=chartDays.map(d=>Object.entries(counts).filter(([k])=>k.startsWith(d)).reduce((a,[,v])=>a+v,0)),max=Math.max(...vals,1);const month=new Date(statDate+'T12:00:00'),mstart=new Date(month.getFullYear(),month.getMonth(),1,12),mlast=new Date(month.getFullYear(),month.getMonth()+1,0,12),monthLogs=active(db.logs).filter(l=>l.date>=day(mstart)&&l.date<=day(mlast));return textBtn(icon('back')+' 返回我的','me')+heading('看见长期的积累',start+' — '+end,'','YOUR GROWTH, OVER TIME')+`<div class="row wrap">${tabs(['day','week','month','year','custom'].map(k=>({day:'日',week:'周',month:'月',year:'年',custom:'自定'}[k])),{day:'日',week:'周',month:'月',year:'年',custom:'自定'}[filters.stats],'stats')}<label class="field" style="max-width:180px">${filters.stats==='custom'?'开始日期':'查看日期'}<input type="date" id="stat-date" value="${statDate}"></label>${filters.stats==='custom'?`<label class="field" style="max-width:180px">结束日期<input type="date" id="stats-end" value="${statEnd}"></label>`:''}</div><div class="stat-grid"><button class="stat-card" data-action="range-logs" data-id="${start}|${end}"><strong>${s.pages}</strong><span>阅读页数 ↗</span></button><button class="stat-card" data-action="range-logs" data-id="${start}|${end}"><strong>${s.minutes}</strong><span>已记录分钟 · ${s.timed}/${s.logs.length} 次填写</span></button><button class="stat-card" data-action="range-books" data-id="${start}|${end}"><strong>${s.books}</strong><span>完成书籍 ↗</span></button><button class="stat-card" data-action="range-thoughts" data-id="${start}|${end}"><strong>${s.thoughts}</strong><span>新增思想 ↗</span></button></div><div class="grid two"><div class="card"><h3>阅读趋势 <small class="muted">/ 页</small></h3><div class="chart">${chartDays.map((d,i)=>`<div class="bar-col"><button title="${d}：${vals[i]}页" data-action="range-logs" data-id="${d.length===7?d+'-01':d}|${d.length===7?day(new Date(Number(d.slice(0,4)),Number(d.slice(5,7)),0,12)):d}"><small>${vals[i]||''}</small><div class="bar" style="height:${Math.max(3,vals[i]/max*105)}px"></div><small>${chartDays.length<=12?d.slice(5):i%5===0?d.slice(8):'·'}</small></button></div>`).join('')}</div></div><div class="card"><div class="row"><h3>阅读日历</h3><span class="months">${statDate.slice(0,7)}</span></div><div class="calendar">${['一','二','三','四','五','六','日'].map(x=>`<small class="muted" style="text-align:center">${x}</small>`).join('')}${'<span></span>'.repeat((mstart.getDay()+6)%7)}${Array.from({length:mlast.getDate()},(_,i)=>{const d=day(new Date(month.getFullYear(),month.getMonth(),i+1,12)),ls=monthLogs.filter(l=>l.date===d),n=ls.reduce((s,l)=>s+l.pages,0);return `<button class="cal-day ${ls.length?n>=30?'strong':'read':''}" data-action="history" data-id="${d}" title="${d}：${n}页">${i+1}</button>`}).join('')}</div></div><div class="card"><h3>这段时间，关注什么</h3><div class="chips">${Object.entries(tags).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<button class="chip tag-button" data-action="search-tag" data-id="${esc(k)}"># ${esc(k)} · ${v}</button>`).join('')||'<p class="small muted">给思想添加标签后，会在这里看到主题分布。</p>'}</div><p class="form-help">同一张卡片可以属于多个主题。</p></div><div class="card"><h3>从阅读走向行动</h3><div class="detail-meta"><span><b>${s.experiments}</b>新建实验</span><span><b>${s.ended}</b>结束实验</span><span><b>${s.changes.length}</b>判断变化</span></div>${textBtn('查看本期实验 →','range-experiments',start+'|'+end)}${s.changes.map(x=>`<div class="link-row">${textBtn(esc(x.thought.title),'open-thought',x.thought.id)}${chip(x.revision.status)}</div>`).join('')}</div></div>`}
function renderReports(){const labels={day:'每日',week:'每周',month:'每月',year:'每年'};return textBtn(icon('back')+' 返回我的','me')+heading('把经历，整理成理解','数据由记录汇总，重要的意义由你写下。',btn(icon('plus')+'新建复盘','new-report'),'PAUSE & REFLECT')+`<div class="report-list">${active(db.reports).sort((a,b)=>b.start.localeCompare(a.start)).map(r=>`<article class="card clickable" data-action="open-report" data-id="${r.id}" role="button" tabindex="0"><div class="row"><div><div class="eyebrow">${labels[r.period]}复盘</div><h3>${esc(r.title)}</h3><p class="subtitle">${r.start} — ${r.end}</p></div>${icon('arrow')}</div></article>`).join('')||emptyView('给这一段阅读留个回望','汇总已有记录，再补充你自己的发现。',btn('生成一份复盘','new-report'))}</div>`}
function renderReport(id){const r=db.reports.find(x=>x.id===id);if(!r)return missing();const changed=r.snapshot!==snapshot(db,r.start,r.end);return textBtn(icon('back')+' 返回复盘','reports')+heading(esc(r.title),r.start+' — '+r.end,btn(icon('download')+'导出','export-report',id),'READING REFLECTION')+`${changed?`<div class="banner warn">源记录有更新。刷新统计不会改动你的反思。${textBtn('刷新统计','refresh-report',id)}</div>`:''}<div class="two-col"><section class="card"><h3>这段时间的记录</h3><div class="report-text" style="margin-top:20px">${esc(r.snapshot)}</div></section><section class="card"><div class="section-head"><h3>我的复盘</h3>${textBtn('编辑','edit-report',id)}</div><div class="prose">${esc(r.body)||'哪些观点留下了影响？有什么判断发生了改变？下一步想读什么？'}</div></section></div><div class="section">${textBtn('移入回收站','delete-report',id)}</div>`}
function renderSettings(){return textBtn(icon('back')+' 返回我的','me')+heading('照顾好你的积累','记录保存在当前浏览器或主屏幕应用的本地空间。','','DATA & PEACE OF MIND')+`<div class="two-col"><div class="stack"><section class="card settings-list"><h3>数据备份</h3><button data-action="backup">${icon('download')}<span>导出完整 JSON 备份<small>${db.settings.lastBackup?'上次导出：'+db.settings.lastBackup.slice(0,10):'尚未导出备份'} · 请将文件保存到「文件」App</small></span>${icon('arrow')}</button><button data-action="import">${icon('upload')}<span>从 JSON 恢复<small>先校验并预览，再确认替换</small></span>${icon('arrow')}</button><button data-action="rollback">${icon('shield')}<span>恢复替换前的本地快照<small>用于撤回最近一次整库恢复</small></span>${icon('arrow')}</button><button data-action="backup-reminder">${icon('clock')}<span>备份提醒<small>超过7天未导出时在「我的」提示</small></span>${chip(db.settings.remindBackup?'已开启':'已关闭')}</button><button data-action="trash">${icon('trash')}<span>回收站<small>删除的内容可以恢复，清空前会确认</small></span>${icon('arrow')}</button></section><section class="card"><h3>保存与离线状态</h3><p class="small muted" style="margin-top:12px">数据存储：本地数据库<br>离线资源：<span id="offline-status">${offlineReady?'已准备好':'准备中 / 请保持联网后重新打开'}</span><br>当前网络：${navigator.onLine?'在线':'离线'}<br>数据版本：${VERSION}</p>${textBtn('重新检查离线准备','check-offline')}</section></div><div class="stack"><section class="card"><h3>在 iPhone 上使用</h3><p class="prose" style="margin-top:16px">1. 在 Safari 打开应用链接。\n2. 点击分享，选择「添加到主屏幕」。\n3. 如果出现「作为 Web App 打开」，保持开启。\n4. 从主屏幕打开一次，确认离线资源已准备好。</p><div class="inset-note">建议始终从同一个主屏幕入口使用。不同浏览器、设备或入口的数据空间可能不同；迁移时使用 JSON 备份。</div></section><section class="card"><h3>属于你的本地记录</h3><p class="small muted" style="margin-top:14px;line-height:1.9">拾页不上传你的阅读内容，也没有应用内账户。清除网站数据、移除设备或更换浏览器前，请先导出备份。\n网页托管的访问权限由发布平台管理。</p></section></div></div>`}
function renderTrash(){const items=TABLES.flatMap(k=>db[k].filter(x=>x.deletedAt&&!x.purged).map(x=>({k,x})));const fs=db.experiments.flatMap(e=>e.feedback.filter(f=>f.deletedAt).map(f=>({e,f})));return textBtn(icon('back')+' 返回设置','settings')+heading('回收站','这里的内容暂不计入统计。',btn('清空回收站','empty-trash','','danger'),'RECENTLY REMOVED')+`<div class="card">${items.map(({k,x})=>`<div class="link-row"><div><h3>${esc(x.title||x.note||titleBook(x.bookId)||'阅读记录')}</h3><p>${{books:'书籍',logs:'阅读记录',thoughts:'思想卡片',experiments:'实验',reports:'复盘'}[k]} · ${x.deletedAt.slice(0,10)}</p></div>${textBtn('恢复','restore-item',JSON.stringify({k,id:x.id}))}</div>`).join('')}${fs.map(({e,f})=>`<div class="link-row"><div><h3>${esc(f.event)}</h3><p>实验反馈 · ${esc(e.title)}</p></div>${textBtn('恢复','restore-feedback',JSON.stringify({id:e.id,fid:f.id}))}</div>`).join('')}${!items.length&&!fs.length?emptyView('回收站是空的','删除的记录会先来到这里。'):''}</div>`}
function searchResults(q){if(!q.trim())return emptyView('找回过去的理解','试试书名、一个标签，或你正在思考的问题。');const needle=q.toLowerCase(),match=(...x)=>x.join(' ').toLowerCase().includes(needle),results=[];active(db.books).forEach(b=>{if(match(b.title,b.author,b.summary))results.push(['书籍',b.title,b.summary||b.author,'book/'+b.id])});active(db.logs).forEach(l=>{if(match(l.note,titleBook(l.bookId)))results.push(['阅读收获',titleBook(l.bookId),l.date+' · '+l.note,'book/'+l.bookId])});active(db.thoughts).forEach(t=>{if(match(t.title,t.understanding,t.authorView,t.question,...t.tags,...t.bookIds.map(titleBook)))results.push(['思想 · 当前理解',t.title,t.understanding,'thought/'+t.id]);t.history.slice(0,-1).forEach(h=>{if(match(h.title,h.understanding,h.authorView,h.question,h.reason,...h.tags))results.push(['思想 · 过去的理解 · '+day(new Date(h.at)),h.title,h.understanding,'thought/'+t.id+'/history'])})});active(db.experiments).forEach(e=>{if(match(e.title,e.hypothesis,e.action,e.conclusion,e.observe,e.stop,...e.feedback.filter(f=>!f.deletedAt).flatMap(f=>[f.event,f.meaning])))results.push(['实践实验',e.title,e.hypothesis,'experiment/'+e.id])});active(db.reports).forEach(r=>{if(match(r.title,r.body,r.snapshot))results.push(['复盘报告',r.title,r.body,'report/'+r.id])});return `<p class="small muted">找到 ${results.length} 条相关内容</p>${results.map(([type,title,body,path])=>`<a href="#${path}" class="card search-result"><span class="eyebrow">${type}</span><h3>${esc(title)}</h3><p>${esc(body.length>220?body.slice(0,220)+'…':body)}</p></a>`).join('')||emptyView('暂时没有找到','换一个关键词试试，历史版本也在搜索范围内。')}`}
function renderSearch(){const searchQuery=globalSearchQuery;return textBtn(icon('back')+' 返回今日','today')+heading('找回一个想法','书籍、收获、思想、实践和复盘，一起查找。','','FIND YOUR PAST THINKING')+`<div class="searchbox">${icon('search')}<input id="global-search" placeholder="搜索「职业」「决策」或一个问题…" aria-label="全局搜索" value="${esc(searchQuery)}" autocomplete="off"></div><div id="search-results">${searchResults(searchQuery)}</div>`}
function render(){route=(location.hash.slice(1)||'today').split('/');const views={today:renderToday,books:renderBooks,book:()=>renderBook(route[1]),thoughts:renderThoughts,thought:()=>renderThought(route[1]),experiments:renderExperiments,experiment:()=>renderExperiment(route[1]),me:renderMe,stats:renderStats,reports:renderReports,report:()=>renderReport(route[1]),settings:renderSettings,trash:renderTrash,search:renderSearch};$('#app').innerHTML=shell((views[route[0]]||renderToday)());document.title='拾页 · '+({today:'今日阅读',books:'我的书架',thoughts:'思想卡片',experiments:'实践实验',me:'我的成长'}[route[0]]||'记录阅读，积累思想');}
const field=(label,name,value='',type='text',required=false,hint='')=>`<label class="field">${label}${hint?`<span class="hint">${hint}</span>`:''}${type==='textarea'?`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" max="10000000" step="1" inputmode="numeric"':''} ${type==='text'?'maxlength="500"':''}>`}</label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const checks=(label,name,options,values=[])=>`<div class="field">${label}<div class="checks">${options.map(o=>`<label class="check"><input type="checkbox" name="${name}" value="${o.id}" ${values.includes(o.id)?'checked':''}>${esc(o.title)}${o.deletedAt?'（已删除）':''}</label>`).join('')||'<p class="small muted">暂无可关联内容</p>'}</div></div>`;
function closeModal(clear=false){if(modalKey){if(clear){try{localStorage.removeItem('shiye-draft:'+modalKey)}catch{}}else saveDraft()}$('#modal-root').innerHTML='';document.body.style.overflow='';modalKey='';modalCallback=null;focusBefore?.focus?.();}
function saveDraft(){if(!modalKey||!$('#edit-form'))return;try{const f=$('#edit-form'),data=Object.fromEntries(new FormData(f));for(const name of new Set([...f.querySelectorAll('input[type=checkbox]')].map(e=>e.name)))data[name]=[...f.querySelectorAll('input[type=checkbox]')].filter(e=>e.name===name&&e.checked).map(e=>e.value);localStorage.setItem('shiye-draft:'+modalKey,JSON.stringify(data));const el=$('#draft-status');if(el)el.textContent='草稿已留在此设备'}catch{const el=$('#draft-status');if(el)el.textContent='草稿未保存，请勿关闭'}}
function modal(title,body,onSubmit,{key='',saveLabel='保存',extra='',readOnly=false}={}){if($('#edit-form'))saveDraft();focusBefore=document.activeElement;modalKey=key;modalCallback=onSubmit;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></header><div class="modal-scroll"><form id="edit-form">${body}<p class="error" id="form-error" role="alert"></p></form></div><footer class="modal-foot">${readOnly?btn('关闭','close-modal','','secondary'):`${extra}<span class="draft-status" id="draft-status">${key?'可稍后继续':''}</span><button class="btn" type="submit" form="edit-form">${saveLabel}</button>`}</footer></section></div>`;document.body.style.overflow='hidden';let restored=false;if(key)try{const d=JSON.parse(localStorage.getItem('shiye-draft:'+key)||'null');if(d){for(const el of $('#edit-form').elements){if(!el.name||!(el.name in d))continue;if(el.type==='checkbox')el.checked=Array.isArray(d[el.name])&&d[el.name].includes(el.value);else el.value=d[el.name]}restored=true;$('#draft-status').textContent='已恢复未保存的草稿'}}catch{};setTimeout(()=>{const focus=$('.modal .icon-btn');focus?.focus()},30);return restored;}
function formData(form){const fd=new FormData(form),v=Object.fromEntries(fd);v.all=name=>fd.getAll(name);return v}
const asNum=(v,fallback=0)=>v===''||v===undefined?fallback:Number(v);
const requireText=(v,label)=>{if(!String(v||'').trim())throw Error('请填写'+label);return v.trim()};
function checkDate(v,label){if(!validDate(v))throw Error('请填写有效的'+label);return v}
function logForm(id=null,bookId=null,date=null){const l=id?db.logs.find(x=>x.id===id):null,books=active(db.books);if(l&&!books.some(b=>b.id===l.bookId))books.push(book(l.bookId));if(!books.length){bookForm(null,()=>logForm());return}books.sort((a,b)=>(a.status==='在读'?-1:1)-(b.status==='在读'?-1:1)||b.updatedAt.localeCompare(a.updatedAt));const selected=l?.bookId||bookId||books[0]?.id;modal(l?'编辑阅读记录':'记录这一段阅读',`${select('正在阅读','bookId',books.map(b=>[b.id,b.title]),selected)}<div class="form-row">${field('本次阅读','pages',l?.pages??'','number',false,'页')}${field('阅读时长','minutes',l?.minutes??'','number',false,'分钟 · 可选')}</div>${field('一句话收获','note',l?.note||'','textarea',false,'可选')}<div class="form-row">${field('日期','date',l?.date||date||day(),'date',true)}${field('时间','time',l?.time||dateTime(),'time',true)}</div><details><summary>更多 · 当前位置 / 添加书籍</summary>${field('本次读至第几页','position',l?.position??'','number',false,'可选，不等于本次阅读量')}<p class="form-help">只在明确填写时更新书籍的当前位置。补录历史记录不会覆盖更新的进度。</p>${textBtn('＋ 添加另一本书','add-book-in-log')}</details><p class="form-help">页数和时长至少填一项。重读也可以记录，不必填写收获。</p>`,async v=>{const pages=asNum(v.pages),minutes=asNum(v.minutes,null),position=asNum(v.position,null);if(pages<=0&&!(minutes>0))throw Error('请填写大于0的页数或阅读时长');checkDate(v.date,'日期');if(v.date>day())throw Error('阅读记录不能晚于今天');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(v.time))throw Error('请填写有效时间');const record={...(l||fresh()),bookId:v.bookId,pages,minutes,note:v.note.trim(),date:v.date,time:v.time,position,updatedAt:stamp()};await commit(d=>{if(l)d.logs[d.logs.findIndex(x=>x.id===id)]=record;else d.logs.push(record);const b=d.books.find(b=>b.id===v.bookId);if(b.status==='想读')b.status='在读';if(!b.started||v.date<b.started)b.started=v.date;if(position!==null&&(!b.positionDate||v.date+v.time>=b.positionDate)){b.position=position;b.percent=null;b.positionDate=v.date+v.time}b.updatedAt=stamp()});closeModal(true);toast('阅读记录已保存',!l?async()=>{await softDelete('logs',record.id,false);toast('已撤销本次记录')}:null)}, {key:'log:'+(id||'new'),extra:l?btn('删除','delete-log',id,'danger'):''});}
function bookForm(id=null,after=null){const b=id?book(id):null;modal(b?'编辑书籍':'让一本书住进书架',`${field('书名','title',b?.title||'','text',true)}${field('作者','author',b?.author||'')}${select('阅读状态','status',['想读','在读','已读','暂停'],b?.status||'想读')}<details ${b?'open':''}><summary>更多资料 · 页数、进度和日期</summary><div class="form-row">${field('总页数','total',b?.total||'','number')}${field('当前读至','position',b?.position||'','number',false,'页')}</div>${field('电子书进度','percent',b?.percent??'','number',false,'0—100%，选填优先使用')}<div class="form-row">${field('开始日期','started',b?.started||'','date')}${field('完成日期','finished',b?.finished||'','date')}</div></details><p class="form-help">只填书名也可以。封面会根据书名自动生成。</p>`,async v=>{const percent=asNum(v.percent,null),total=asNum(v.total),position=asNum(v.position);if(percent!==null&&(percent<0||percent>100))throw Error('进度百分比应在0到100之间');if(total&&position>total)throw Error('当前位置不能大于总页数');if(v.started)checkDate(v.started,'开始日期');if(v.finished)checkDate(v.finished,'完成日期');const finished=v.status==='已读'?(v.finished||day()):'';if(v.started&&finished&&finished<v.started)throw Error('完成日期不能早于开始日期');const item={...(b||fresh()),title:requireText(v.title,'书名'),author:v.author.trim(),status:v.status,total,position,percent,started:v.started||(v.status==='在读'?day():''),finished,summary:b?.summary||'',rating:b?.rating||0,updatedAt:stamp()};if(!b||b.position!==position||b.percent!==percent)item.positionDate=day()+dateTime();await commit(d=>{if(b)d.books[d.books.findIndex(x=>x.id===id)]=item;else d.books.push(item)});closeModal(true);toast('书籍已保存');if(after)after(item.id)}, {key:'book:'+(id||'new')});}
function revision(t,kind,reason='',experimentId=null){return {id:uid(),at:stamp(),kind,reason,experimentId,title:t.title,understanding:t.understanding,authorView:t.authorView,question:t.question,status:t.status,tags:[...t.tags],bookIds:[...t.bookIds]}}
function thoughtForm(id=null,{bookId=null,logId=null}={}){const t=id?thought(id):null,l=logId?db.logs.find(x=>x.id===logId):null,selected=t?.bookIds||[bookId||l?.bookId].filter(Boolean);modal(t?'编辑思想文字':'留下一个想法',`${field('我的理解','understanding',t?.understanding||l?.note||'','textarea',true)}${field('卡片标题','title',t?.title||'','text',false,'留空时取首句')}${select('当前状态','status',statuses,t?.status||'新收获')}${field('标签','tags',t?.tags.join('，')||'','text',false,'用逗号分隔')}<details ${t?'open':''}><summary>深入一点 · 来源、作者观点与疑问</summary>${checks('来源书籍 · 可多选','bookIds',db.books.filter(b=>!b.deletedAt||selected.includes(b.id)),selected)}${field('作者观点','authorView',t?.authorView||'','textarea')}${field('我的疑问','question',t?.question||'','textarea')}</details><p class="form-help">编辑会保留修订历史。如果经历改变了你的判断，可使用「更新判断」留下原因。</p>`,async v=>{const understanding=requireText(v.understanding,'我的理解'),item={...(t||fresh()),title:v.title.trim()||understanding.split(/[。！？\n]/)[0].slice(0,36),understanding,authorView:v.authorView.trim(),question:v.question.trim(),status:v.status,tags:[...new Set(v.tags.split(/[,，#\n]/).map(x=>x.trim()).filter(Boolean))],bookIds:v.all('bookIds'),logId:t?.logId||logId||null,links:t?.links||[],history:t?.history||[],updatedAt:stamp()};item.history=[...item.history,revision(item,t?'编辑文字':'初次记录')];await commit(d=>{if(t)d.thoughts[d.thoughts.findIndex(x=>x.id===id)]=item;else d.thoughts.push(item)});closeModal(true);toast('想法已留下');if(!t)go('thought/'+item.id)}, {key:'thought:'+(id||logId||bookId||'new')});}
function judgmentForm(id,eid=null){const t=thought(id);modal('更新我的判断',`${field('现在，我的理解是','understanding',t.understanding,'textarea',true)}${select('当前状态','status',statuses,t.status)}${field('为什么发生了变化','reason','','textarea',true,'经历、证据或新问题')}${select('关联实践证据','experimentId',[['','暂不关联'],...db.experiments.map(e=>[e.id,e.title])],eid||'')}<p class="form-help">旧理解会保留在时间线上。更新判断不代表必须实践，也不要求得出确定答案。</p>`,async v=>{await commit(d=>{const item=d.thoughts.find(x=>x.id===id);item.understanding=requireText(v.understanding,'新的理解');item.status=v.status;item.updatedAt=stamp();item.history.push(revision(item,'更新判断',requireText(v.reason,'改变原因'),v.experimentId||null))});closeModal(true);toast('新的判断已保存，旧版本仍然保留')},{key:'judgment:'+id});}
function linkForm(id){const t=thought(id),options=active(db.thoughts).filter(o=>o.id!==id&&!t.links.some(l=>l.target===o.id));if(!options.length){toast('请先创建另一张尚未关联的思想卡片');return}modal('建立思想之间的联系',`${field('查找卡片','findTarget','','text',false,'输入关键词筛选下方选项')}${select('关联到','target',options.map(o=>[o.id,o.title]),options[0].id)}${select('这张卡片与对方的关系','type',['相关','支持','补充','质疑'],'相关')}${field('关联的理由','reason','','textarea',false,'可选')}<p class="form-help">支持和质疑有方向：当前卡片 → 对方。对方也会显示这条关联。</p>`,async v=>{if(!v.target)throw Error('请选择一张卡片');await commit(d=>{const item=d.thoughts.find(x=>x.id===id);item.links.push({target:v.target,type:v.type,reason:v.reason.trim()});item.updatedAt=stamp()});closeModal(true);toast('关联已建立')},{key:'link:'+id});}
function experimentForm(id=null,tid=null){const e=id?experiment(id):null,selected=e?.thoughtIds||(tid?[tid]:[]);modal(e?'编辑实验计划':'开始一个小实验',`${field('我想验证什么','hypothesis',e?.hypothesis||'','textarea',true)}${field('我准备怎么做','action',e?.action||'','textarea',true)}${field('实验名称','title',e?.title||'','text',false,'留空时根据想法生成')}<div class="form-row">${field('开始日期','start',e?.start||day(),'date',true)}${field('预计复盘','due',e?.due||'','date')}</div><details ${e?'open':''}><summary>更多 · 来源与观察线索</summary>${checks('来源思想 · 可多选','thoughtIds',db.thoughts.filter(t=>!t.deletedAt||selected.includes(t.id)),selected)}${field('准备观察哪些现象','observe',e?.observe||'','textarea')}${field('调整或停止的条件','stop',e?.stop||'','textarea')}</details>`,async v=>{checkDate(v.start,'开始日期');if(v.due){checkDate(v.due,'复盘日期');if(v.due<v.start)throw Error('复盘日期不能早于开始日期')}const hypothesis=requireText(v.hypothesis,'想验证的想法'),item={...(e||fresh()),title:v.title.trim()||hypothesis.slice(0,30),hypothesis,action:requireText(v.action,'准备采取的行动'),observe:v.observe.trim(),stop:v.stop.trim(),thoughtIds:v.all('thoughtIds'),start:v.start,due:v.due,status:e?.status||'进行中',ended:e?.ended||'',feedback:e?.feedback||[],verdict:e?.verdict||'',conclusion:e?.conclusion||'',updatedAt:stamp()};await commit(d=>{if(e)d.experiments[d.experiments.findIndex(x=>x.id===id)]=item;else d.experiments.push(item)});closeModal(true);toast('实验计划已保存');if(!e)go('experiment/'+item.id)},{key:'experiment:'+(id||tid||'new')});}
function feedbackForm(id,fid=null){const e=experiment(id),f=e.feedback.find(x=>x.id===fid);modal(f?'编辑实践反馈':'留下一条实践反馈',`${field('记录日期','date',f?.date||day(),'date',true)}${field('发生了什么','event',f?.event||'','textarea',true)}${field('这对原来的判断意味着什么','meaning',f?.meaning||'','textarea',false,'可选')}`,async v=>{checkDate(v.date,'记录日期');if(v.date>day())throw Error('反馈日期不能晚于今天');await commit(d=>{const item=d.experiments.find(x=>x.id===id),newF={id:fid||uid(),date:v.date,event:requireText(v.event,'发生的事情'),meaning:v.meaning.trim()};if(fid)item.feedback[item.feedback.findIndex(x=>x.id===fid)]=newF;else item.feedback.push(newF);item.updatedAt=stamp()});closeModal(true);toast('实践反馈已保存')},{key:'feedback:'+id+':'+(fid||'new'),extra:fid?btn('删除','delete-feedback',JSON.stringify({id,fid}),'danger'):''});}
function concludeForm(id){const e=experiment(id);modal('给这次实验一个回望',`${select('当前结论','verdict',['目前支持','部分支持','暂不支持','证据不足'],e.verdict||'证据不足')}${field('我的结论与依据','conclusion',e.conclusion,'textarea',true)}${field('复盘日期','ended',e.ended||day(),'date',true)}<p class="form-help">保存后实验标为已结束。来源思想不会自动被改写，你可以随后逐张更新。</p>`,async v=>{checkDate(v.ended,'复盘日期');if(v.ended<e.start)throw Error('复盘日期不能早于开始日期');if(v.ended>day())throw Error('复盘日期不能晚于今天');await commit(d=>{const item=d.experiments.find(x=>x.id===id);Object.assign(item,{conclusion:requireText(v.conclusion,'结论'),verdict:v.verdict,status:'已结束',ended:v.ended,updatedAt:stamp()})});closeModal(true);toast('实验已复盘，可继续更新来源思想')},{key:'conclude:'+id});}
function summaryForm(id){const b=book(id);modal('我的读后总结',`${select('个人评分','rating',[['0','暂不评分'],...Array.from({length:5},(_,i)=>[String(i+1),'★'.repeat(i+1)])],String(b.rating))}${field('这本书留下了什么','summary',b.summary||'这本书主要讲了什么？\n\n哪三个观点影响最大？\n\n哪些观点我仍然存疑？\n\n准备尝试应用什么？\n','textarea')}<p class="form-help">可以自由改写这些问题，也可以只写最重要的一点。</p>`,async v=>{await commit(d=>{const item=d.books.find(x=>x.id===id);item.summary=v.summary.trim();item.rating=Number(v.rating);item.updatedAt=stamp()});closeModal(true);toast('总结已保存')},{key:'summary:'+id});}
function reportForm(id=null){const r=db.reports.find(x=>x.id===id);modal(r?'编辑我的复盘':'生成一份阅读复盘',r?`${field('报告标题','title',r.title,'text',true)}${field('我的复盘','body',r.body,'textarea')}`:`${select('复盘周期','period',[['day','每日'],['week','每周'],['month','每月'],['year','每年']],'week')}${field('选择周期内的一天','date',day(),'date',true)}<p class="form-help" id="report-range">${range('week').join(' — ')} · 按周一至周日统计</p>${field('我的复盘','body','最重要的观点：\n\n我的判断发生了什么变化：\n\n实践中的发现：\n\n下一步的阅读计划：\n','textarea')}<p class="form-help">数据汇总来自已有记录，反思内容由你填写。</p>`,async v=>{let item;if(r)item={...r,title:requireText(v.title,'标题'),body:v.body,updatedAt:stamp()};else{checkDate(v.date,'日期');const [start,end]=range(v.period,v.date);item={...fresh(),title:start+' · '+{day:'每日',week:'每周',month:'每月',year:'年度'}[v.period]+'阅读复盘',period:v.period,start,end,body:v.body,snapshot:snapshot(db,start,end),sourceUpdatedAt:db.updatedAt}}await commit(d=>{if(r)d.reports[d.reports.findIndex(x=>x.id===id)]=item;else d.reports.push(item)});closeModal(true);go('report/'+item.id);toast('复盘已保存')},{key:'report:'+(id||'new'),saveLabel:r?'保存复盘':'生成并保存'});}
function historyModal(date=day()){const logs=active(db.logs).filter(l=>l.date===date);modal('阅读记录 · '+date,`${field('选择日期','historyDate',date,'date')}<div id="history-logs">${logs.map(logRow).join('')||emptyView('这天还没有记录','可以补录过去的阅读。')}</div>${btn('补录这一天','new-log-date',date,'full secondary')}`,null,{readOnly:true});}
function confirmModal(title,description,callback){modal(title,`<p class="prose">${description}</p>`,async()=>{await callback();closeModal(true)},{saveLabel:'确认'});}
async function softDelete(k,id,notify=true){await commit(d=>{const item=d[k].find(x=>x.id===id);item.deletedAt=stamp();item.updatedAt=stamp()});closeModal(true);if(['book','thought','experiment','report'].includes(route[0]))go({book:'books',thought:'thoughts',experiment:'experiments',report:'reports'}[route[0]]);if(notify)toast('已移入回收站',async()=>{await commit(d=>{delete d[k].find(x=>x.id===id).deletedAt});toast('已恢复')})}
function download(name,content,type='text/markdown;charset=utf-8',isBackup=false){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),safeName=name.replace(/[\\/:*?"<>|]/g,'_');pendingExport={blob,url,name:safeName,content,isBackup};modal('保存或分享文件',`<p class="prose">${esc(safeName)}</p><p class="form-help">${Math.ceil(blob.size/1024)} KB · 在 iPhone 上可通过系统分享选择「存储到文件」。</p><div class="action-wrap"><a id="export-download" class="btn" href="${url}" download="${esc(safeName)}">${icon('download')} 保存文件</a>${btn('系统分享','share-export','','secondary')}${!isBackup?btn('复制 Markdown','copy-export','','secondary'):''}</div><p class="form-help">点击后请确认文件已保存。文件只在你的设备上生成。</p>`,null,{readOnly:true});$('#export-download').addEventListener('click',()=>{if(isBackup)commit(d=>d.settings.lastBackup=stamp()).catch(e=>toast(e.message))});setTimeout(()=>URL.revokeObjectURL(url),600000);return blob}
function bookMarkdown(id){const b=book(id),logs=active(db.logs).filter(l=>l.bookId===id).sort((a,b)=>a.date.localeCompare(b.date)),ts=active(db.thoughts).filter(t=>t.bookIds.includes(id));return `# ${b.title}\n\n作者：${b.author||'未填写'}\n状态：${b.status}\n累计阅读：${logs.reduce((s,l)=>s+l.pages,0)}页\n\n## 阅读与收获\n\n${logs.map(l=>`### ${l.date} ${l.time}\n\n${l.pages}页 · ${l.minutes===null?'时长未记录':l.minutes+'分钟'}\n\n${l.note}`).join('\n\n')}\n\n## 思想卡片\n\n${ts.map(t=>`### ${t.title}\n\n状态：${t.status}\n标签：${t.tags.join('、')}\n\n作者观点：${t.authorView}\n\n我的理解：${t.understanding}\n\n我的疑问：${t.question}\n\n关联：${t.links.map(l=>l.type+' '+thought(l.target)?.title).join('；')}\n\n#### 理解的变化\n\n${t.history.map(h=>`- ${day(new Date(h.at))} / ${h.kind} / ${h.status}：${h.understanding}${h.reason?'（原因：'+h.reason+'）':''}`).join('\n')}`).join('\n\n')}\n\n## 最终总结\n\n${b.summary}\n\n评分：${b.rating||'未评分'}`}
async function backup(){const at=stamp(),copy=structuredClone(db);copy.settings.lastBackup=at;download('拾页-完整备份-'+day()+'.json',JSON.stringify({app:'拾页',exportedAt:at,data:copy},null,2),'application/json',true)}
async function importFile(file){if(!file)return;if(file.size>25*1024*1024){toast('备份文件超过25MB，请检查文件');return}try{pendingImport=validate(JSON.parse(await file.text()));modal('预览备份 · 尚未替换',`<p class="small muted">备份数据更新于 ${esc(day(new Date(pendingImport.updatedAt)))}</p><div class="detail-meta">${TABLES.map(k=>`<span><b>${pendingImport[k].length}</b>${{books:'书籍',logs:'阅读记录',thoughts:'思想',experiments:'实验',reports:'报告'}[k]}</span>`).join('')}</div><div class="banner warn">恢复将替换当前全部记录。当前数据会另存为本地快照，建议先导出独立备份。</div>${btn('先导出当前备份','backup','','secondary')}<p class="form-help">先导出会打开导出窗口；完成后请重新选择备份文件进行恢复。</p><label class="check" style="margin-top:20px"><input type="checkbox" name="confirm" required>我确认用这份备份替换当前数据</label>`,async()=>{const old=structuredClone(db),next=structuredClone(pendingImport);next.updatedAt=stamp();await writeStore(next,old,db.updatedAt);db=next;pendingImport=null;closeModal(true);go('me');render();toast('备份已恢复，替换前快照已保留')},{saveLabel:'确认恢复'})}catch(e){toast('未导入：'+e.message)}}
async function act(action,id,el){
 if(['today','books','thoughts','experiments','me','stats','reports','settings','trash','search'].includes(action)){closeModal();searchQuery='';if(action==='thoughts')tagFilter='';go(action);return}
 if(action==='close-modal'){closeModal();return}
 if(action.startsWith('open-')){closeModal();if(action==='open-thought')thoughtTab='当前理解';if(action==='open-book')bookTab='阅读';go(action.slice(5)+'/'+id);return}
 if(action==='filter'){const key=el.dataset.key;if(key==='bookTab')bookTab=id;else if(key==='thoughtTab')thoughtTab=id;else if(key==='stats'){filters.stats={'日':'day','周':'week','月':'month','年':'year','自定':'custom'}[id];if(statEnd<statDate)statEnd=statDate}else filters[key]=id;render();return}
 if(action==='tag'){tagFilter=tagFilter===id?'':id;render();return}
 if(action==='search-tag'){globalSearchQuery=id;go('search');return}
 if(action==='new-log'){logForm(null,id||null);return}
 if(action==='edit-log'){logForm(id);return}
 if(action==='new-log-date'){logForm(null,null,id);return}
 if(action==='new-book'){bookForm();return}
 if(action==='edit-book'){bookForm(id);return}
 if(action==='add-book-in-log'){saveDraft();bookForm(null,bid=>{try{const key='shiye-draft:log:new',v=JSON.parse(localStorage.getItem(key)||'{}');v.bookId=bid;localStorage.setItem(key,JSON.stringify(v))}catch{}logForm(null,bid)});return}
 if(action==='finish-book'){await commit(d=>{const b=d.books.find(x=>x.id===id);b.status='已读';b.finished=day();b.updatedAt=stamp()});toast('已标记读完，总结可以慢慢写');return}
 if(action==='summary'){summaryForm(id);return}
 if(action==='new-thought'){thoughtForm();return}
 if(action==='edit-thought'){thoughtForm(id);return}
 if(action==='from-log'){thoughtForm(null,{logId:id});return}
 if(action==='book-thought'){thoughtForm(null,{bookId:id});return}
 if(action==='judgment'){judgmentForm(id);return}
 if(action==='judgment-evidence'){const p=JSON.parse(id);judgmentForm(p.tid,p.eid);return}
 if(action==='link-thought'){linkForm(id);return}
 if(action==='unlink'){const p=JSON.parse(id);await commit(d=>{const t=d.thoughts.find(x=>x.id===p.owner);t.links=t.links.filter(l=>l.target!==p.target);t.updatedAt=stamp()});toast('关联已移除');return}
 if(action==='restore-thought'){const {id:tid,hid}=JSON.parse(id),t=thought(tid),h=t.history.find(x=>x.id===hid);confirmModal('恢复这一版理解？','将把当前内容恢复到 '+day(new Date(h.at))+' 的版本，并新增一条修订记录。现有历史会保留。',async()=>{await commit(d=>{const item=d.thoughts.find(x=>x.id===tid);for(const k of ['title','understanding','authorView','question','status','tags','bookIds'])item[k]=structuredClone(h[k]);item.updatedAt=stamp();item.history.push(revision(item,'恢复版本','恢复到 '+day(new Date(h.at))+' 的理解'))});toast('已恢复，并保留全部历史')});return}
 if(action==='new-experiment'){experimentForm();return}
 if(action==='edit-experiment'){experimentForm(id);return}
 if(action==='thought-experiment'){experimentForm(null,id);return}
 if(action==='feedback'){feedbackForm(id);return}
 if(action==='edit-feedback'){const p=JSON.parse(id);feedbackForm(p.id,p.fid);return}
 if(action==='delete-feedback'){const p=JSON.parse(id);await commit(d=>{d.experiments.find(e=>e.id===p.id).feedback.find(f=>f.id===p.fid).deletedAt=stamp()});closeModal(true);toast('反馈已移入回收站');return}
 if(action==='restore-feedback'){const p=JSON.parse(id);await commit(d=>{delete d.experiments.find(e=>e.id===p.id).feedback.find(f=>f.id===p.fid).deletedAt});toast('反馈已恢复');return}
 if(action==='pause-experiment'||action==='reopen-experiment'){await commit(d=>{const e=d.experiments.find(x=>x.id===id);if(action==='reopen-experiment'){if(e.conclusion)e.feedback.push({id:uid(),date:day(),event:'重新开始实验，保留前次结论：'+e.verdict,meaning:e.conclusion});e.status='进行中';e.ended='';e.verdict='';e.conclusion='';e.due=''}else e.status=e.status==='已暂停'?'进行中':'已暂停';e.updatedAt=stamp()});toast('实验状态已更新');return}
 if(action==='conclude'){concludeForm(id);return}
 if(action==='new-report'){reportForm();return}
 if(action==='edit-report'){reportForm(id);return}
 if(action==='refresh-report'){await commit(d=>{const r=d.reports.find(x=>x.id===id);r.snapshot=snapshot(d,r.start,r.end);r.sourceUpdatedAt=db.updatedAt;r.updatedAt=stamp()});toast('统计已刷新，你的反思已保留');return}
 if(action==='export-book'){download(titleBook(id)+'-阅读笔记.md',bookMarkdown(id));return}
 if(action==='export-report'){const r=db.reports.find(x=>x.id===id);download(r.title+'.md',`# ${r.title}\n\n${r.start} — ${r.end}\n\n## 记录汇总\n\n${r.snapshot}\n\n## 我的复盘\n\n${r.body}`);return}
 if(action==='history'){historyModal(id||day());return}
 if(action.startsWith('range-')){const [start,end]=id.split('|'),s=statistics(db,start,end);let body='';if(action==='range-logs')body=s.logs.map(l=>`<p class="small muted">${l.date}</p>${logRow(l)}`).join('');if(action==='range-books')body=active(db.books).filter(b=>b.status==='已读'&&b.finished>=start&&b.finished<=end).map(bookCard).join('');if(action==='range-thoughts')body=active(db.thoughts).filter(t=>day(new Date(t.createdAt))>=start&&day(new Date(t.createdAt))<=end).map(thoughtCard).join('');if(action==='range-experiments')body=active(db.experiments).filter(e=>(e.start>=start&&e.start<=end)||(e.ended>=start&&e.ended<=end)).map(experimentCard).join('');modal(start+' — '+end,body||emptyView('这段时间没有相关记录','积累可以慢慢来。'),null,{readOnly:true});return}
 const deleteMap={'delete-book':'books','delete-log':'logs','delete-thought':'thoughts','delete-experiment':'experiments','delete-report':'reports'};
 if(deleteMap[action]){await softDelete(deleteMap[action],id);return}
 if(action==='restore-item'){const {k,id:rid}=JSON.parse(id);await commit(d=>{delete d[k].find(x=>x.id===rid).deletedAt});toast('已恢复');return}
 if(action==='empty-trash'){confirmModal('永久清空回收站？','这会永久删除回收站中的内容，无法撤销。仍被引用的书籍将仅保留匿名来源标识，以保护阅读记录的完整性。',async()=>{await commit(d=>{const dead={};TABLES.forEach(k=>dead[k]=new Set(d[k].filter(x=>x.deletedAt).map(x=>x.id)));d.books=d.books.filter(b=>!b.deletedAt||d.logs.some(l=>l.bookId===b.id&&!l.deletedAt)||d.thoughts.some(t=>!t.deletedAt&&(t.bookIds.includes(b.id)||t.history.some(h=>h.bookIds.includes(b.id)))));for(const b of d.books.filter(b=>b.deletedAt)){Object.assign(b,{title:'已删除书籍',author:'',summary:'',total:0,position:0,percent:null,rating:0,started:'',finished:'',purged:true})}d.logs=d.logs.filter(x=>!x.deletedAt);d.thoughts=d.thoughts.filter(x=>!x.deletedAt);d.experiments=d.experiments.filter(x=>!x.deletedAt);d.reports=d.reports.filter(x=>!x.deletedAt);const retainedBooks=new Set(d.books.map(b=>b.id));for(const t of d.thoughts){t.links=t.links.filter(l=>!dead.thoughts.has(l.target));t.bookIds=t.bookIds.filter(x=>retainedBooks.has(x));if(dead.logs.has(t.logId))t.logId=null;for(const h of t.history){h.bookIds=h.bookIds.filter(x=>retainedBooks.has(x));if(dead.experiments.has(h.experimentId))h.experimentId=null}}for(const e of d.experiments){e.thoughtIds=e.thoughtIds.filter(x=>!dead.thoughts.has(x));e.feedback=e.feedback.filter(f=>!f.deletedAt)}});toast('回收站已清空')});return}
 if(action==='share-export'){if(!pendingExport)return;const f=new File([pendingExport.blob],pendingExport.name,{type:pendingExport.blob.type});if(!navigator.canShare?.({files:[f]})){toast('当前浏览器不支持文件分享，请使用「保存文件」');return}try{await navigator.share({files:[f],title:pendingExport.name});if(pendingExport.isBackup)await commit(d=>d.settings.lastBackup=stamp());toast('已交给系统分享，请确认保存完成')}catch(e){if(e.name!=='AbortError')throw e}return}
 if(action==='copy-export'){if(pendingExport){await navigator.clipboard.writeText(pendingExport.content);toast('Markdown 已复制')}return}
 if(action==='backup'){await backup();return}
 if(action==='backup-reminder'){await commit(d=>d.settings.remindBackup=!d.settings.remindBackup);return}
 if(action==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.style.display='none';document.body.append(input);input.onchange=()=>{const file=input.files[0];input.remove();importFile(file)};input.addEventListener('cancel',()=>input.remove(),{once:true});input.click();return}
 if(action==='rollback'){const prev=await readPrevious();if(!prev){toast('还没有整库恢复前的快照');return}validate(prev);confirmModal('恢复替换前的快照？','将用上次整库恢复前的快照替换当前数据。当前数据会成为新的可回退快照。',async()=>{const old=structuredClone(db),next=structuredClone(prev);next.updatedAt=stamp();await writeStore(next,old,db.updatedAt);db=next;render();toast('已恢复替换前的快照')});return}
 if(action==='check-offline'){await prepareOffline();toast(offlineReady?'离线资源已准备好':'暂未完成，请保持联网后重试');return}
}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();if(busy)return;try{await act(el.dataset.action,el.dataset.id||'',el)}catch(e){console.error(e);toast(e.message||'操作未完成，请重试')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#edit-form')){if(!busy)closeModal();return}if($('#modal-root .modal')&&e.key==='Tab'){const nodes=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal summary')].filter(x=>!x.disabled&&x.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click()}});
document.addEventListener('submit',async ev=>{if(ev.target.id!=='edit-form')return;ev.preventDefault();if(!modalCallback||busy)return;busy=true;const button=$('button[form="edit-form"]');button.disabled=true;$('#form-error').textContent='';try{await modalCallback(formData(ev.target))}catch(e){console.error(e);if($('#form-error'))$('#form-error').textContent=e.message||'保存失败，表单已保留，请重试';else toast(e.message)}finally{busy=false;if(button?.isConnected)button.disabled=false}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.closest('#edit-form'))saveDraft();if(el.id==='global-search'){globalSearchQuery=el.value;$('#search-results').innerHTML=searchResults(globalSearchQuery)}if(el.id==='local-search'){const pos=el.selectionStart;searchQuery=el.value;render();const x=$('#local-search');x?.focus();x?.setSelectionRange(pos,pos)}if(el.name==='findTarget'){const opts=$('select[name="target"]')?.options;if(opts){for(const o of opts)o.hidden=!o.textContent.toLowerCase().includes(el.value.toLowerCase());const first=[...opts].find(o=>!o.hidden);$('select[name="target"]').value=first?.value||''}}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='thought-sort'){thoughtSort=el.value;render()}if(el.id==='stat-date'){if(validDate(el.value)){statDate=el.value;if(statEnd<statDate)statEnd=statDate;render()}}if(el.id==='stats-end'&&validDate(el.value)){if(el.value<statDate){toast('结束日期不能早于开始日期');el.value=statEnd}else{statEnd=el.value;render()}}if(el.name==='historyDate'&&validDate(el.value))historyModal(el.value);if(['period','date'].includes(el.name)&&$('#report-range')){const f=$('#edit-form'),period=f.elements.period.value,date=f.elements.date.value;if(validDate(date))$('#report-range').textContent=range(period,date).join(' — ')}});
window.addEventListener('hashchange',()=>{closeModal();const next=(location.hash.slice(1)||'today').split('/');if(next[0]!==route?.[0]&&next[0]!=='search')searchQuery='';if(next[0]==='thought')thoughtTab=next[2]==='history'?'变化记录':'当前理解';render();window.scrollTo(0,0)});
window.addEventListener('pagehide',()=>saveDraft());
async function prepareOffline(){if(!('serviceWorker' in navigator)||!isSecureContext)return;try{await navigator.serviceWorker.register('./sw.js');await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('离线准备超时')),12000))]);const cache=await caches.open('shiye-shell-v4-icon-blue');offlineReady=!!(await cache.match('./index.html'));if($('#offline-status'))$('#offline-status').textContent=offlineReady?'已准备好':'尚未准备好'}catch(e){console.warn('Offline preparation:',e.message)}}
try{db=await readStore();if(!location.hash)history.replaceState(null,'','#today');render();prepareOffline();navigator.storage?.persist?.().catch(()=>{});}catch(e){$('#app').innerHTML=`<div class="loading">暂时无法打开本地记录<span>${esc(e.message)}</span><p class="small muted" style="max-width:400px;margin:20px">原数据未被清空。请关闭其他窗口后重新打开；不要清除网站数据。如果仍无法打开，请保留最近导出的 JSON 备份。</p><button class="btn" onclick="location.reload()">重新打开</button></div>`;console.error(e)}
